  return{T,palette,mat,mesh,box,cyl,ball,torus,seeded,beam,island,tree,grass,plankFloor,railing,dock,barrel,crate,lantern,sign,potion,stall,arch,chest,windmill,vane,character,animateCharacter,ship,beacon,house};
